"""Let LaTeX read its numbers from the analysis: every value becomes a macro in one generated file.

    write_values("build/values.tex", {"nTested": 265500, "pTrend": (0.185, 3)})     then \\input it and write \\nTested in the text
"""
import re
from pathlib import Path


def macro_name(key):
    """LaTeX macro names hold letters only, so digits and separators are spelt out."""
    words = {"0": "Zero", "1": "One", "2": "Two", "3": "Three", "4": "Four", "5": "Five", "6": "Six", "7": "Seven", "8": "Eight", "9": "Nine"}
    parts = re.split(r"[^A-Za-z0-9]+", str(key))
    out = "".join(p[:1].upper() + p[1:] for p in parts if p)
    out = "".join(words.get(c, c) for c in out)
    return out[:1].lower() + out[1:]


def fmt(value):
    """A pair (value, decimals) sets the precision; whole numbers get thousands separators."""
    if isinstance(value, tuple):
        return f"{value[0]:,.{value[1]}f}".replace(",", "{,}")
    if isinstance(value, bool):
        return "yes" if value else "no"
    if isinstance(value, int):
        return f"{value:,}".replace(",", "{,}")
    return str(value)


def write_values(path, values, header="Generated by the analysis. Do not edit."):
    lines = [f"% {header}"]
    seen = set()
    for k, v in values.items():
        name = macro_name(k)
        if name in seen:
            raise ValueError(f"two keys give the macro {name}")
        seen.add(name)
        lines.append(f"\\newcommand{{\\{name}}}{{{fmt(v)}}}")
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text("\n".join(lines) + "\n", encoding="utf8")
    return p
